{
  "name": "Cornerstone 7400 单色仪",
  "name_en": "Cornerstone 7400 Monochromator",
  "manufacturer": "Oriel",
  "description": "一款可电动调节输出波长并带有快门的光学单色仪，用于从宽带光源中选择窄带光，并在光谱测量、显微成像和材料光学表征实验中进行波长扫描与光路控制。",
  "description_en": "A motorized optical monochromator with a shutter, used to select narrowband light from a broadband source and to perform wavelength scanning and light-path control in spectroscopy, microscopy, and optical characterization experiments.",
  "tag_hints": [
    "monochromator",
    "wavelength selection",
    "optical spectroscopy",
    "wavelength scanning",
    "motorized shutter",
    "broadband light source"
  ],
  "actions": [
    {
      "action_name": "auto-setShutter",
      "description": "设置快门状态。",
      "description_en": "Set the shutter state."
    },
    {
      "action_name": "auto-getShutter",
      "description": "获取快门状态。",
      "description_en": "Get the shutter state."
    },
    {
      "action_name": "auto-setWavelength",
      "description": "设置输出波长。",
      "description_en": "Set the output wavelength."
    },
    {
      "action_name": "auto-getWavelength",
      "description": "获取当前输出波长。",
      "description_en": "Get the current output wavelength."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "设置波长位置。",
      "description_en": "Set the wavelength position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "获取当前波长位置。",
      "description_en": "Get the current wavelength position."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "获取控制就绪状态。",
      "description_en": "Get the control-ready status."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取当前控制通道信息。",
      "description_en": "Get the current control-channel information."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取当前通道相位状态。",
      "description_en": "Get the current channel phase status."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取最小波长位置限制。",
      "description_en": "Get the minimum wavelength position limit."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取最大波长位置限制。",
      "description_en": "Get the maximum wavelength position limit."
    },
    {
      "action_name": "auto-IsOn",
      "description": "获取设备输出启用状态。",
      "description_en": "Get the device output enabled state."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "开启设备输出。",
      "description_en": "Enable device output."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭设备输出。",
      "description_en": "Disable device output."
    }
  ]
}

